 19→UW_QuestionDisplay::UW_QuestionDisplay(const FObjectInitializer& ObjectInitializer)
 20→    : Super(ObjectInitializer)
 21→{
 22→    // 8-bit color scheme
 23→    BackgroundColor = FUEBridgeStyle::GetColor("Color.Background");
 24→    QuestionTextColor = FUEBridgeStyle::GetColor("Color.Cyan");
 25→    ProgressTextColor = FUEBridgeStyle::GetColor("Color.TextDim");
 26→}
