 29→TSharedRef<SWidget> UW_QuestionDisplay::RebuildWidget()
 30→{
 31→    if (!QuestionText || !OptionsContainer)
 32→    {
 33→        BuildWidgetTree();
 34→    }
 35→    return Super::RebuildWidget();
 36→}
