 38→
 39→void UW_QuestionDisplay::NativeConstruct()
 40→{
 41→    Super::NativeConstruct();
 42→
 43→    // Apply colors
 44→    if (BackgroundBorder)
 45→    {
 46→        BackgroundBorder->SetBrushColor(BackgroundColor);
 47→    }
 48→    if (QuestionText)
 49→    {
 50→        QuestionText->SetColorAndOpacity(FSlateColor(QuestionTextColor));
 51→    }
 52→    if (ProgressText)
 53→    {
 54→        ProgressText->SetColorAndOpacity(FSlateColor(ProgressTextColor));
 55→    }
 56→
 57→    UE_LOG(LogUEBridge, Log, TEXT("[W_QuestionDisplay] Constructed (Programmatic UI)"));
 58→}
 59→
 60→
 61→void UW_QuestionDisplay::BuildWidgetTree()
 62→{
 63→    // Create root canvas
 64→    UCanvasPanel* RootCanvas = WidgetTree->ConstructWidget<UCanvasPanel>(UCanvasPanel::StaticClass(), TEXT("RootCanvas"));
 65→    WidgetTree->RootWidget = RootCanvas;
 66→
 67→    // Create background border - centered panel
 68→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
 69→    BackgroundBorder->SetBrushColor(BackgroundColor);
 70→    BackgroundBorder->SetPadding(FMargin(40.0f, 30.0f));
 71→
 72→    UCanvasPanelSlot* BorderSlot = RootCanvas->AddChildToCanvas(BackgroundBorder);
 73→    if (BorderSlot)
 74→    {
 75→        // Center the panel
 76→        BorderSlot->SetAnchors(FAnchors(0.5f, 0.5f, 0.5f, 0.5f));
 77→        BorderSlot->SetAlignment(FVector2D(0.5f, 0.5f));
 78→        BorderSlot->SetAutoSize(true);
 79→    }
 80→
 81→    // Create main vertical layout
 82→    UVerticalBox* MainLayout = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("MainLayout"));
 83→    BackgroundBorder->AddChild(MainLayout);
 84→
 85→    // Create size box to constrain width
 86→    USizeBox* ContentSizeBox = WidgetTree->ConstructWidget<USizeBox>(USizeBox::StaticClass(), TEXT("ContentSizeBox"));
 87→    ContentSizeBox->SetWidthOverride(600.0f);
 88→    UVerticalBoxSlot* SizeBoxSlot = MainLayout->AddChildToVerticalBox(ContentSizeBox);
 89→    if (SizeBoxSlot)
 90→    {
 91→        SizeBoxSlot->SetHorizontalAlignment(HAlign_Center);
 92→    }
 93→
 94→    // Inner vertical box for content
 95→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
 96→    ContentSizeBox->AddChild(ContentBox);
 97→
 98→    // Depth label (top - e.g. "SURFACE", "PATTERNS", etc.)
 99→    DepthText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("DepthText"));
100→    DepthText->SetText(NSLOCTEXT("UEBridge", "QuestionDisplay.DefaultDepth", "SURFACE"));
